import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.k9nOhppk.js";const g=JSON.parse('{"title":"What runs today","description":"","frontmatter":{"title":"What runs today"},"headers":[],"relativePath":"reference/status.md","filePath":"reference/status.md","lastUpdated":1791864160000}'),d={name:"reference/status.md"};function s(n,e,c,l,i,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="what-runs-today" tabindex="-1">What runs today <a class="header-anchor" href="#what-runs-today" aria-label="Permalink to &quot;What runs today&quot;">​</a></h1><p>The <a href="/reference/language/">language reference</a> describes Eyelang as it is designed. This page says how much of each part is built. It describes the code at commit <code>856485a</code> on 2026-10-13, and it is updated with each merge.</p><p>Each feature has three columns:</p><ul><li><strong>Parses</strong>: both parsers accept it. The conformance suite checks that they agree on every file in <code>testdata/syntax/valid</code> and on the tree-sitter corpus, and every example in the spec is one of those files. Every example also passes the checker, in the program from <code>testdata/specctx</code> that its fence names, apart from the one marked as waiting for a task (6.8, the <code>agents</code> module); see <a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/specdoc/check_test.go#L26" target="_blank" rel="noreferrer">specdoc&#39;s check_test.go</a>.</li><li><strong>Checks</strong>: <code>eye check</code> resolves and type-checks it, or reports a specific error when it is misused.</li><li><strong>Runs</strong>: the reference interpreter runs it, and a passing test shows that.</li></ul><p>A cell holds ✓ (done), &quot;partial&quot; with what is missing, &quot;—&quot; (not built), or &quot;n/a&quot; (the column doesn&#39;t apply). A feature with &quot;—&quot; under Checks and Runs is <strong>spec only</strong>: it parses, and then it is rejected or ignored. &quot;Shown by&quot; links to a test or program that shows the feature working. For compile-time errors it links to the checker&#39;s test cases. Every error class the spec promises is listed in <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/classes_test.go" target="_blank" rel="noreferrer">check/classes_test.go</a>, along with the test that reports it.</p><p><strong>The biggest gaps today.</strong> Coding agents, and native compilation of entities, jobs, views and contracts (v0.4): <code>eye build</code> compiles the core language only.</p><h2 id="a-tour" tabindex="-1"><a href="/reference/language/a-tour">A tour</a> <a class="header-anchor" href="#a-tour" aria-label="Permalink to &quot;[A tour](/reference/language/a-tour)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>The tour: an entity, a view, a job that waits, a contract with fakes, three tests</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye#L57" target="_blank" rel="noreferrer">programs/tour</a></td></tr></tbody></table><h2 id="lexical-structure" tabindex="-1"><a href="/reference/language/lexical-structure">Lexical structure</a> <a class="header-anchor" href="#lexical-structure" aria-label="Permalink to &quot;[Lexical structure](/reference/language/lexical-structure)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>#</code> comments; <code>##</code> doc comments with a summary, <code>[Name]</code> links and a module doc</td><td>✓</td><td>partial: links are checked by <code>eye doc</code>, not <code>eye check</code></td><td>✓ (they become a model schema&#39;s descriptions)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/apidoc/apidoc_test.go#L12" target="_blank" rel="noreferrer">apidoc_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L243" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td>Names: upper case for types, lower case for values</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/syntax/conformance_test.go#L56" target="_blank" rel="noreferrer">conformance</a></td></tr><tr><td>Int, Float, String with interpolation, Bool, Unit</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L56" target="_blank" rel="noreferrer">core: integers, strings</a></td></tr><tr><td>Hex and binary integers, <code>0xC2</code> and <code>0b1010_0101</code>, for <code>Int</code> and the fixed-width types; <code>eye fmt</code> keeps the base and writes hex digits upper case; <code>0x</code> without a digit is an error that says so</td><td>✓</td><td>✓</td><td>✓ (compiled by <code>eye build</code> too)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/bytelevel.eye#L71" target="_blank" rel="noreferrer">core: bytes</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/syntax/valid/hex-binary.eye" target="_blank" rel="noreferrer">conformance</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/fmt/literals.golden.eye" target="_blank" rel="noreferrer">fmt</a></td></tr><tr><td>Char literals and escapes</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L117" target="_blank" rel="noreferrer">core: match</a></td></tr><tr><td>Duration and Size literals</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L70" target="_blank" rel="noreferrer">core: strings</a></td></tr><tr><td>Time of day, Date, Instant, next time of day in a zone</td><td>✓</td><td>✓ (a date or time that doesn&#39;t exist, such as <code>25:00</code> or <code>2026-02-30</code>, is an error at the literal)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L185" target="_blank" rel="noreferrer">core: time</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L199" target="_blank" rel="noreferrer">programs/jobs: <code>07:45 in zone</code></a></td></tr><tr><td>A zone given by name or by a <code>Zone</code> value, checked when compiled</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L231" target="_blank" rel="noreferrer">core: zones</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L156" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Multi-line strings with a margin</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L194" target="_blank" rel="noreferrer">core: multi-line</a></td></tr><tr><td>Contextual keywords (<code>state</code>, <code>view</code>, <code>type</code>, <code>test</code> as names)</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/syntax/valid/contextual-names.eye" target="_blank" rel="noreferrer">contextual-names.eye</a></td></tr><tr><td>Newlines end statements; <code>;</code> separates them</td><td>✓</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/syntax/valid/newlines.eye" target="_blank" rel="noreferrer">newlines.eye</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L138" target="_blank" rel="noreferrer">core: pipes</a></td></tr><tr><td>Braces only for blocks; one-expression branches; <code>{</code> after <code>=&gt;</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/syntax/valid/arm-records.eye" target="_blank" rel="noreferrer">arm-records.eye</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L208" target="_blank" rel="noreferrer">core: branches</a></td></tr><tr><td>Waiting calls <code>f!(x)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L26" target="_blank" rel="noreferrer">programs/jobs</a></td></tr></tbody></table><h2 id="values-and-types" tabindex="-1"><a href="/reference/language/values-and-types">Values and types</a> <a class="header-anchor" href="#values-and-types" aria-label="Permalink to &quot;[Values and types](/reference/language/values-and-types)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>Int</code> with arbitrary precision</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L56" target="_blank" rel="noreferrer">core: integers</a></td></tr><tr><td><code>NonZero(Int)</code> divisors and <code>nonzero(n)</code></td><td>✓</td><td>✓ (<code>/</code> and <code>%</code> on an <code>Int</code> take a <code>NonZero(Int)</code> or a literal other than 0)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L316" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>average</code>, <code>div</code> and <code>rem</code>: division that gives an <code>Option</code> instead of needing a <code>NonZero</code></td><td>✓</td><td>✓ (<code>average</code> takes <code>Int</code>s or <code>Float</code>s and gives an <code>Option(Float)</code>; <code>div</code> and <code>rem</code> take two <code>Int</code>s)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L270" target="_blank" rel="noreferrer">core: div</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L280" target="_blank" rel="noreferrer">core: average</a></td></tr><tr><td><code>Float</code>: IEEE 754, but NaN equals itself and <code>0.0</code> doesn&#39;t equal <code>-0.0</code>; shown as <code>NaN</code>, <code>+Inf</code> and <code>-Inf</code>, which JSON refuses</td><td>✓</td><td>✓</td><td>✓ (<code>eye build</code>&#39;s runtime still shows NaN as <code>NaN.0</code>, 7.9)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L98" target="_blank" rel="noreferrer">core: match</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L254" target="_blank" rel="noreferrer">interp_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L371" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td><code>Byte</code>, <code>Bytes</code>, <code>Int32</code>, <code>Int64</code>, <code>UInt32</code>, <code>UInt64</code></td><td>✓</td><td>✓ (<code>wrappingAdd</code>, <code>checkedAdd</code> and the rest of SPECS §5&#39;s methods, <code>T.from(n)</code>, <code>x.toInt()</code>; <code>+</code> and the other operators are errors that name the methods; a literal too large for its type is an error at its span; an ASCII character literal is a <code>Byte</code> where one is expected)</td><td>✓ (a fixed-width value is an <code>Int</code> at run time, and its methods take the width from the receiver&#39;s type in the typed IR)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/fixed.eye#L3" target="_blank" rel="noreferrer">core: fixed</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/strings.eye#L82" target="_blank" rel="noreferrer">core: bytes</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/fixed_test.go#L13" target="_blank" rel="noreferrer">fixed_test.go</a></td></tr><tr><td><code>Instant</code>, <code>Date</code>, <code>Time</code>, <code>Duration</code>, <code>Zone</code>, <code>Schedule</code>, <code>Size</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L185" target="_blank" rel="noreferrer">core: time</a></td></tr><tr><td>Durations as numbers: <code>d.seconds()</code>, <code>d.millis()</code>, <code>d / NonZero(Int)</code>, and <code>d / e</code>, a <code>Float</code></td><td>✓</td><td>✓</td><td>✓ in the interpreter; <code>eye build</code> doesn&#39;t compile them yet</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/times_test.go#L32" target="_blank" rel="noreferrer">times_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L820" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>List</code>, <code>Map</code>, <code>Set</code> as values; <code>xs + ys</code> joins lists and gives the union of sets</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L156" target="_blank" rel="noreferrer">core: collections</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/callbacks.eye#L24" target="_blank" rel="noreferrer">core: callbacks</a></td></tr><tr><td>Tuples, and lambdas that take a tuple&#39;s parts</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L147" target="_blank" rel="noreferrer">core: closures</a></td></tr><tr><td>Records, <code>with</code> updates, field assignment</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L74" target="_blank" rel="noreferrer">core: records</a></td></tr><tr><td>Nominal records; a literal takes the type expected, in a lambda&#39;s body too, from where the call&#39;s result goes</td><td>✓</td><td>✓ (a call takes the type expected of it before its lambdas are checked, so a later stage reads the fields; a literal nested in a settled one takes its field&#39;s type)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/rows.eye#L34" target="_blank" rel="noreferrer">core: rows</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L134" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Variants, one-variant types, aliases</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L3" target="_blank" rel="noreferrer">core</a></td></tr><tr><td><code>Option</code> and <code>Result</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L124" target="_blank" rel="noreferrer">core: errors</a></td></tr><tr><td>Type variables</td><td>✓</td><td>✓ (one can&#39;t be called or indexed; a requirement on an untyped parameter waits for its calls)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L33" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L261" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Ranges <code>..</code> and <code>..=</code>, as loops, patterns and values that compare, hash and show as they are written; time ranges that wrap midnight</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L94" target="_blank" rel="noreferrer">core: mutation</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L329" target="_blank" rel="noreferrer">core: ranges</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/notifier/notifier.eye#L242" target="_blank" rel="noreferrer">lab notifier: quiet hours</a></td></tr><tr><td>Slices <code>xs[a..b]</code>; <code>s.slice(range)</code> on strings, by <code>Offset</code>, with <code>indexOf</code>, <code>start</code>, <code>end</code>, <code>after</code>, <code>before</code> and <code>charAt</code>; an <code>Int</code> there is an error that says where offsets come from</td><td>✓</td><td>✓</td><td>✓ (compiled by <code>eye build</code>, a slice of a list or of <code>Bytes</code> copies what it covers instead of sharing storage, so <code>bytes[i..]</code> costs the rest of the bytes)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L166" target="_blank" rel="noreferrer">core: collections</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/strings.eye#L3" target="_blank" rel="noreferrer">core: strings</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/offset_test.go" target="_blank" rel="noreferrer">offset_test.go</a></td></tr><tr><td>Regular expressions, <code>import regex</code>: <code>regex.parse</code> (RE2: no backreferences, linear time), <code>matches</code> on the whole text, <code>find</code> and <code>findAll</code> with each <code>Match</code>&#39;s range and groups, <code>replace</code> and <code>replaceFirst</code> with <code>$1</code> and <code>$&lt;name&gt;</code>, <code>split</code>, <code>escape</code></td><td>✓</td><td>✓ (a <code>Regex</code> is opaque, so only <code>regex.parse</code> makes one; its methods are pure)</td><td>✓ (Go&#39;s <code>regexp</code>, each pattern compiled once; compiled by <code>eye build</code> as host calls the Go runner answers with the same <code>regexp</code>, which test binaries are answered with today: <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/regex/regex.eye" target="_blank" rel="noreferrer">programs/regex</a> passes natively)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/regex/regex.eye#L15" target="_blank" rel="noreferrer">programs/regex</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/regex_test.go#L14" target="_blank" rel="noreferrer">regex_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye#L640" target="_blank" rel="noreferrer">the digest&#39;s hrefOf</a></td></tr><tr><td>Iteration with <code>for</code>; <code>s.chars()</code>; lazy <code>xs.iter()</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/iter.eye#L6" target="_blank" rel="noreferrer">core: iter</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L279" target="_blank" rel="noreferrer">checker cases</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L94" target="_blank" rel="noreferrer">core: mutation</a></td></tr><tr><td><code>Ref(E)</code>, different for each entity</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L35" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td><code>Secret(a)</code>: no printing, no saving</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L180" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>Approval</code>, made only by <code>approval!</code>, with <code>what</code> and <code>by</code></td><td>✓</td><td>✓: a <code>@destructive</code> command or function requires one, and <code>ok.what</code> and <code>ok.by</code> read what was approved and by whom</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/approvals.eye#L64" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/access/access.eye#L192" target="_blank" rel="noreferrer">lab access</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/contracts/contracts.eye#L116" target="_blank" rel="noreferrer">programs/contracts</a></td></tr><tr><td><code>Version</code>: a snapshot&#39;s <code>version</code>, <code>==</code> and no order, from an integer literal</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/contracts/contracts.eye#L130" target="_blank" rel="noreferrer">programs/contracts</a></td></tr><tr><td><code>Key</code>, <code>Run(a)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L101" target="_blank" rel="noreferrer">programs/limits</a></td></tr><tr><td>A program&#39;s <code>extern type</code>, whose values foreign code owns: not saved, shown or compared (<code>Handle</code> is gone, open question 21)</td><td>✓</td><td>✓</td><td>— (no foreign code yet)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L285" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>opaque</code> types</td><td>✓</td><td>✓ (other modules can&#39;t read, write, build or match its fields or variants)</td><td>✓ as an ordinary type</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/visibility_test.go#L35" target="_blank" rel="noreferrer">visibility_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/syntax/valid/spec-08-methods-and-generics-1.eye" target="_blank" rel="noreferrer">spec-08 example</a></td></tr><tr><td>String literals as <code>Key</code> or <code>Zone</code> where one is expected</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L145" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Map literals, <code>(key):</code> keys, <code>{ name, age }</code> shorthand, <code>{}</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L156" target="_blank" rel="noreferrer">core: collections</a></td></tr></tbody></table><h2 id="bindings-functions-and-pipes" tabindex="-1"><a href="/reference/language/bindings-functions-and-pipes">Bindings, functions and pipes</a> <a class="header-anchor" href="#bindings-functions-and-pipes" aria-label="Permalink to &quot;[Bindings, functions and pipes](/reference/language/bindings-functions-and-pipes)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>Public functions with full signatures; private ones inferred, and generic where their bodies leave types open</td><td>✓</td><td>✓ (each call decides the open types, and must give the operators and traits the body uses)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L151" target="_blank" rel="noreferrer">core</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L261" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>let</code>, <code>var</code>, shadowing</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L83" target="_blank" rel="noreferrer">core: mutation</a></td></tr><tr><td>Lambdas: one expression, a block, several parameters, none</td><td>✓</td><td>✓ (a parameter may state its type, <code>fn (item: Item) { … }</code>, which must be what the lambda is given)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L147" target="_blank" rel="noreferrer">core: closures</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L718" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Data-first pipes and <code>_</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L134" target="_blank" rel="noreferrer">core: pipes</a></td></tr><tr><td><code>?</code> after a piped call</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L52" target="_blank" rel="noreferrer">core</a></td></tr><tr><td><code>if</code> as an expression, <code>then</code>, blocks</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L30" target="_blank" rel="noreferrer">core</a></td></tr><tr><td><code>for</code>, <code>while</code>, <code>break</code>, <code>continue</code>; <code>while true</code> as any type</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L173" target="_blank" rel="noreferrer">core: loops</a></td></tr><tr><td>Named arguments with defaults</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L143" target="_blank" rel="noreferrer">core: pipes</a></td></tr><tr><td><code>name:</code> passes the variable of that name</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L225" target="_blank" rel="noreferrer">core: labels</a></td></tr><tr><td>A function without <code>-&gt;</code> returns <code>()</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L35" target="_blank" rel="noreferrer">core</a></td></tr><tr><td>Module-level <code>let</code> and <code>pub let</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/home/home.eye#L7" target="_blank" rel="noreferrer">lab home</a></td></tr><tr><td>A branch that is one assignment</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L208" target="_blank" rel="noreferrer">core: branches</a></td></tr><tr><td>Errors for <code>_</code> outside a pipe, <code>return</code> in a lambda, <code>break</code> outside a loop, a name declared twice</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L112" target="_blank" rel="noreferrer">check_test.go</a></td></tr></tbody></table><h2 id="mutation" tabindex="-1"><a href="/reference/language/mutation">Mutation</a> <a class="header-anchor" href="#mutation" aria-label="Permalink to &quot;[Mutation](/reference/language/mutation)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>var</code>, field assignment, <code>+=</code> and the other compound assignments</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L83" target="_blank" rel="noreferrer">core: mutation</a></td></tr><tr><td>Element assignment: <code>xs[i] = v</code> and <code>xs[i] += v</code> on a <code>var</code> or <code>mut</code> list, through fields too (<code>rows[i].x = v</code>, <code>self.open[n] = s</code>), and <code>m[key] = v</code> on a map; an index out of range is a fault</td><td>✓</td><td>✓ (<code>m[key] += v</code>, a field of a map&#39;s value, a byte of <code>Bytes</code>, a slice and <code>mut xs[i]</code> are errors that say what to write)</td><td>✓ (the interpreter copies the list; compiled by <code>eye build</code>, in place when the list holds its only reference, and a slice is copied first)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/bytelevel.eye#L17" target="_blank" rel="noreferrer">core: bytes</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/bytelevel_test.go" target="_blank" rel="noreferrer">bytelevel_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/failures/failures.eye" target="_blank" rel="noreferrer">cgen: failures</a></td></tr><tr><td>A <code>let</code> never changes</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L35" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td><code>mut</code> parameters, with <code>mut</code> written at the call</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L85" target="_blank" rel="noreferrer">core: mutation</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L253" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>mut self</code> methods, only on a <code>var</code> or <code>mut</code> parameter</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L90" target="_blank" rel="noreferrer">core: mutation</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L275" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>No aliasing: no variable passed as <code>mut</code> twice, or as <code>mut</code> and read</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L264" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Only a callback reads a <code>var</code>, a <code>mut</code> parameter or a <code>mut self</code> receiver, as its value at the call, and can&#39;t assign it; a kept or returned closure can&#39;t capture one</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/callbacks.eye#L28" target="_blank" rel="noreferrer">core: callbacks</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L51" target="_blank" rel="noreferrer">check_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L807" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Updates in place when a value is unique</td><td>n/a</td><td>n/a</td><td>partial: appending to a list (<code>xs |&gt; add(x)</code>, <code>xs += [x]</code>, <code>xs + ys</code>), a set&#39;s <code>add</code> and a map&#39;s <code>insert</code> of a new key are in place in the interpreter, and replacing a map&#39;s value copies only O(log n) of it (a persistent vector); <code>s += t</code> and <code>s = s + t</code> on a local <code>String</code> variable append in place; a record that a local variable alone holds, one the interpreter just made, takes field assignment and <code>p = { p with … }</code> in place; other <code>with</code>s and other <code>String +</code> still copy, since the interpreter has no reference counts. Compiled by <code>eye build</code>, counting is precise (7.5, <code>lir.Count</code>): any update whose operand&#39;s last use it is (<code>s += t</code>, <code>xs += ys</code>, <code>xs.add(x)</code>, <code>m.insert(k, v)</code>, a set&#39;s <code>add</code>, <code>remove</code>, <code>{ p with … }</code>, field assignment) changes it in place when it holds the only reference, whether the last use is an assignment, a call or a <code>let</code>, and a field read to rebuild its record is taken out of it first</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L89" target="_blank" rel="noreferrer">core: mutation</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/append_test.go#L63" target="_blank" rel="noreferrer">append_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/shelf_test.go#L168" target="_blank" rel="noreferrer">shelf_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/vec_test.go" target="_blank" rel="noreferrer">vec_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/text_test.go" target="_blank" rel="noreferrer">text_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/control.eye" target="_blank" rel="noreferrer">core: records in place</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/inplace/inplace.eye" target="_blank" rel="noreferrer">cgen: in place</a></td></tr></tbody></table><h2 id="methods-and-generics" tabindex="-1"><a href="/reference/language/methods-and-generics">Methods and generics</a> <a class="header-anchor" href="#methods-and-generics" aria-label="Permalink to &quot;[Methods and generics](/reference/language/methods-and-generics)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>Any function in scope called as a method on its first argument: <code>x.f(a)</code> is <code>f(x, a)</code>, generic and imported ones too, after the type&#39;s methods and a field that holds a function</td><td>✓</td><td>✓ (the receiver&#39;s type must be known; a function that doesn&#39;t take it first, takes no parameters or changes its first parameter is an error that says so; a function only in an imported module gets a hint to import it by name)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/methods.eye#L26" target="_blank" rel="noreferrer">core: methods</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L1289" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>A field that holds a function, called like a method: <code>timer.read()</code></td><td>✓</td><td>✓ (a method named like such a field is an error)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye" target="_blank" rel="noreferrer">programs/traits</a></td></tr><tr><td><code>impl Type { … }</code> methods, and functions called on the type (<code>Lexer.new</code>, and <code>lex.Lexer.new</code> from another module)</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L18" target="_blank" rel="noreferrer">core</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/modules.eye#L3" target="_blank" rel="noreferrer">core: modules</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/visibility_test.go#L35" target="_blank" rel="noreferrer">visibility_test.go</a></td></tr><tr><td>An <code>impl Type</code> only in the module that declares the type</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L117" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td>Generic functions and types with type variables</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L33" target="_blank" rel="noreferrer">programs/traits</a></td></tr><tr><td><code>where</code> requirements, and a trait as a parameter&#39;s type</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L27" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L225" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Generic code specialised at compile time</td><td>n/a</td><td>✓ (<code>eye check --lir</code>: one instance per set of types; polymorphic recursion is an error)</td><td>✓ compiled to C by <code>eye build</code>, for the core language</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/lir/lir_test.go" target="_blank" rel="noreferrer">lir_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/cgen_test.go" target="_blank" rel="noreferrer">cgen_test.go</a></td></tr><tr><td><code>dyn Trait</code> (v0.2)</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L109" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L188" target="_blank" rel="noreferrer">types_test.go</a></td></tr></tbody></table><h2 id="pattern-matching" tabindex="-1"><a href="/reference/language/pattern-matching">Pattern matching</a> <a class="header-anchor" href="#pattern-matching" aria-label="Permalink to &quot;[Pattern matching](/reference/language/pattern-matching)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>Variants with positional or named payloads, guards, alternatives, <code>..</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L98" target="_blank" rel="noreferrer">core: match</a></td></tr><tr><td>Literals, negative numbers, characters, ranges</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L117" target="_blank" rel="noreferrer">core: match</a></td></tr><tr><td>Record and tuple patterns; destructuring <code>let</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/syntax/valid/patterns.eye" target="_blank" rel="noreferrer">patterns.eye</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L152" target="_blank" rel="noreferrer">core: closures</a></td></tr><tr><td>List patterns <code>[first, ..rest]</code> and <code>let … else</code></td><td>✓</td><td>✓ (an <code>else</code> block that doesn&#39;t leave is an error at the block)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L109" target="_blank" rel="noreferrer">core: match</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L130" target="_blank" rel="noreferrer">core: errors</a></td></tr><tr><td>String patterns over <code>Bytes</code> and <code>List(Byte)</code>: <code>&quot;let&quot;</code> matches those bytes, and <code>[&quot;..=&quot;, ..]</code> a prefix</td><td>✓</td><td>✓ (exhaustiveness sees the list patterns they are)</td><td>✓ (compiled by <code>eye build</code> too)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/bytelevel.eye#L102" target="_blank" rel="noreferrer">core: bytes</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/lexer/lexer/token.eye" target="_blank" rel="noreferrer">the lexer in Eyelang</a></td></tr><tr><td>List patterns over <code>Bytes</code> with character literals</td><td>✓</td><td>✓ (<code>[&#39;-&#39;, &#39;-&#39;, ..rest]</code>, <code>Some(&#39;a&#39;..=&#39;z&#39;)</code>; <code>&#39;é&#39;</code> where a <code>Byte</code> is expected is an error at its span)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/fixed.eye#L166" target="_blank" rel="noreferrer">core: fixed</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/fixed_test.go#L13" target="_blank" rel="noreferrer">fixed_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/lexer/lexer/token.eye" target="_blank" rel="noreferrer">the lexer in Eyelang</a></td></tr><tr><td>Variants of imported modules without a prefix; when two modules declare one, the type expected where it is written says which (an argument, a typed <code>let</code>, a return, a field, <code>Some(…)</code>, <code>==</code>, a later use), and only where nothing does is it an error</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/variants/variants.eye" target="_blank" rel="noreferrer">programs/variants</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go" target="_blank" rel="noreferrer">check_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye" target="_blank" rel="noreferrer">programs/tour</a></td></tr><tr><td>Exhaustive matches, including nested patterns and list lengths</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L103" target="_blank" rel="noreferrer">types_test.go</a></td></tr></tbody></table><h2 id="errors-result-only" tabindex="-1"><a href="/reference/language/errors-result-only">Errors: Result only</a> <a class="header-anchor" href="#errors-result-only" aria-label="Permalink to &quot;[Errors: Result only](/reference/language/errors-result-only)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>?</code> on <code>Result</code> and <code>Option</code></td><td>✓</td><td>✓ (the function, job or lambda it returns from must return an <code>Option</code> or a <code>Result</code> in turn; a lambda&#39;s <code>?</code> returns from the lambda and wraps into its error type; a value whose type a later call gives is checked once the function is, and one nothing types is an error that asks for its type)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L124" target="_blank" rel="noreferrer">core: errors</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/wrap.eye#L42" target="_blank" rel="noreferrer">core: wrap</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/try_test.go#L14" target="_blank" rel="noreferrer">try_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L229" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td><code>?</code> wraps the error in the one variant that holds it</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L127" target="_blank" rel="noreferrer">core: errors</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/wrap.eye#L34" target="_blank" rel="noreferrer">core: wrap</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L96" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>A <code>Result</code> can&#39;t be dropped by a statement: it is used, matched, passed on with <code>?</code> or discarded with <code>let _ = …</code>; a block&#39;s last expression is used when the block&#39;s value is, and <code>()</code> and <code>Option</code>s may be dropped</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/drop_test.go#L15" target="_blank" rel="noreferrer">drop_test.go</a></td></tr><tr><td><code>.mapErr(…)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye#L132" target="_blank" rel="noreferrer">lab digest</a></td></tr><tr><td><code>Problem</code> and <code>.context(…)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/problems.eye#L16" target="_blank" rel="noreferrer">core: problems</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/problem_test.go" target="_blank" rel="noreferrer">problem_test.go</a></td></tr><tr><td>Total library functions: <code>xs[i]</code> and <code>first</code> give <code>Option</code>, <code>parseInt</code> and <code>parseFloat</code> give <code>Result</code>, <code>toInt</code> gives <code>Option</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/values.eye#L165" target="_blank" rel="noreferrer">core: collections</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/strings.eye#L60" target="_blank" rel="noreferrer">core: numbers</a></td></tr><tr><td>String functions: <code>replace</code>, <code>words</code>, <code>endsWith</code>, <code>chars</code>, <code>code</code>, <code>fromCode</code>; Float <code>round</code>, <code>floor</code>, <code>ceil</code>, <code>toFloat</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/strings.eye#L39" target="_blank" rel="noreferrer">core: strings</a></td></tr><tr><td><code>unreachable(&quot;why&quot;)</code> ends the program or run as a fault</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L153" target="_blank" rel="noreferrer">interp_test.go: faults</a></td></tr><tr><td>Runtime faults as a run&#39;s outcome</td><td>✓</td><td>✓</td><td>✓ <code>Unreachable</code>, <code>DeadlinePassed</code>, <code>Unavailable</code>, <code>OverBudget</code>, <code>OutOfMemory</code>, <code>LockExpired</code> and <code>Killed</code> (from <code>firstDone!</code>) happen; recursion deeper than 100,000 calls is an <code>Unreachable</code> fault, not a crash (natively a recursion deeper than the stack holds, which is 256 MB, room for the 100,000 calls with frames up to 2.6 KB: <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/recursion/recursion.eye" target="_blank" rel="noreferrer">cgen: recursion</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L101" target="_blank" rel="noreferrer">programs/limits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/waits_test.go#L113" target="_blank" rel="noreferrer">waits_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/depth_test.go#L37" target="_blank" rel="noreferrer">depth_test.go</a></td></tr></tbody></table><h2 id="traits" tabindex="-1"><a href="/reference/language/traits">Traits</a> <a class="header-anchor" href="#traits" aria-label="Permalink to &quot;[Traits](/reference/language/traits)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>Trait declarations, with default methods</td><td>✓</td><td>✓ (a default method sees self as any type with the trait)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L71" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L418" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>impl Trait for Type</code>, every method and no others, with the trait&#39;s types</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L192" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Coherence: an impl lives with its trait or its type, once per type</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L208" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>A one-variant wrapper shows as the value it wraps</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye#L44" target="_blank" rel="noreferrer">programs/tour</a></td></tr><tr><td>Derived <code>Eq</code>, <code>Ord</code>, <code>Show</code>, <code>Hash</code>, <code>Save</code>, <code>Schema</code>, asked for where they are used</td><td>✓</td><td>✓</td><td>✓ (natively, <code>Save</code> is an encoder and a decoder per saved type, writing the interpreter&#39;s bytes: <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/save_test.go" target="_blank" rel="noreferrer">save_test.go</a>; <code>Schema</code>&#39;s JSON is <code>toJson</code>, and decoding JSON stays in the runner)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L98" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L244" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>An impl of <code>Show</code> replaces the derived form, inside lists, <code>Option</code>s and records too</td><td>✓</td><td>✓</td><td>✓ (compiled by <code>eye build</code> too: a descriptor&#39;s show entry calls the impl; <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/shows/shows.eye" target="_blank" rel="noreferrer">cgen: shows</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L100" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/traits_test.go#L11" target="_blank" rel="noreferrer">traits_test.go</a></td></tr><tr><td><code>T.variants()</code>, <code>T.parse(s)</code> and a variant&#39;s number, <code>v.index()</code>, on enums</td><td>✓</td><td>✓ (refused on a record or a type with a variant that has fields)</td><td>✓ (<code>index()</code> compiled by <code>eye build</code> too; <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/bytelevel.eye#L135" target="_blank" rel="noreferrer">core: bytes</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L163" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L772" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/access/access.eye#L188" target="_blank" rel="noreferrer">lab access</a></td></tr><tr><td>Operators as traits (<code>Add</code>, <code>Mul</code>, <code>Neg</code> for <code>-x</code>, …); no implicit conversions</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/traits/traits.eye#L81" target="_blank" rel="noreferrer">programs/traits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L285" target="_blank" rel="noreferrer">types_test.go</a></td></tr></tbody></table><h2 id="effects-and-signatures" tabindex="-1"><a href="/reference/language/effects-and-signatures">Effects and signatures</a> <a class="header-anchor" href="#effects-and-signatures" aria-label="Permalink to &quot;[Effects and signatures](/reference/language/effects-and-signatures)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>uses</code> on public functions; none means pure; a private function&#39;s uses clause and a trait method&#39;s are held too; effect names are checked</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L171" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>uses</code> on public entity methods and public jobs, which <code>eye fmt</code> writes</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L776" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L146" target="_blank" rel="noreferrer">main_test.go</a></td></tr><tr><td><code>start J</code>: starting a job is an effect; in a job, a function that starts one is a step</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L808" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Waiting functions: a function with <code>!</code> steps has <code>wait</code>, and only jobs and other waiting functions call it, with <code>!</code>; outside a job <code>sleep</code>, <code>sleepUntil</code> and <code>poll</code> block and keep <code>wait</code> in the caller&#39;s effects, and a job can&#39;t call a function that blocks</td><td>✓</td><td>✓ (<code>next</code>, <code>approval</code> and <code>reserve</code> outside a run are errors too)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L837" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Effects inferred through private functions and callbacks, and functions passed by name</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L261" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>wait</code>, <code>net C.op</code>, <code>entity E</code>, <code>clock</code>, <code>stdio</code>, <code>env</code></td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L171" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>secret &quot;name&quot;</code>, <code>publish C.event</code>, <code>consume C.event</code>, <code>ffi</code></td><td>✓</td><td>✓ (inferred; <code>consume</code> from <code>next!</code> and from <code>@on(event(…))</code>)</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L379" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>with fakes(process, from: …)</code>: <code>process.run</code> answered from recordings by command line, and <code>calls(process.run)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/fakes_process_test.go" target="_blank" rel="noreferrer">fakes_process_test.go</a></td></tr><tr><td><code>fs</code>, <code>process</code>, <code>random</code>; <code>fs.readBytes</code> and <code>fs.writeBytes</code> for files that aren&#39;t text, and <code>toBytes(list)</code>; <code>fs.lines</code> for a text file&#39;s lines</td><td>✓</td><td>✓</td><td>✓, each test in a directory of its own, with a fixed seed (<code>readBytes</code>, <code>writeBytes</code> and <code>toBytes</code> compiled by <code>eye build</code> too: <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/core/bytelevel.eye#L121" target="_blank" rel="noreferrer">core: bytes</a>; <code>random</code> and <code>fs.lines</code> too, <code>random</code> drawing the interpreter&#39;s numbers from the same seed: <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/hosts/hosts.eye" target="_blank" rel="noreferrer">cgen: hosts</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/system/system.eye#L29" target="_blank" rel="noreferrer">programs/system</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/system/system.eye#L42" target="_blank" rel="noreferrer">lines</a></td></tr><tr><td>Function types in signatures: <code>f: fn(Int) -&gt; Int</code></td><td>✓</td><td>✓ (a function has none of the derived traits, so it can&#39;t be shown, compared or saved)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L406" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Function types kept in data state their effects</td><td>✓</td><td>✓ (calling a function value counts what its type states; a lambda or named function kept where its type states less, a callback kept in data, and a lambda that calls one are errors)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L305" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>In a job or a waiting function, every call with an outside effect, and every entity call, takes <code>!</code></td><td>✓</td><td>✓ (publishing takes <code>publish!</code>, starting a child run <code>start!</code>, an extern call <code>!</code>; a step&#39;s result must be saveable; <code>!</code> on a call that only computes is an error, and printing and logging aren&#39;t steps; a task a waiting function starts only computes, as one a job starts does)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L306" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L114" target="_blank" rel="noreferrer">interp_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L106" target="_blank" rel="noreferrer">programs/jobs</a></td></tr></tbody></table><h2 id="programs-and-concurrency" tabindex="-1"><a href="/reference/language/programs-and-concurrency">Programs and concurrency</a> <a class="header-anchor" href="#programs-and-concurrency" aria-label="Permalink to &quot;[Programs and concurrency](/reference/language/programs-and-concurrency)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>pub fn main</code>, returning <code>()</code> or <code>Result</code>; an <code>Err</code> exits with status 1</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L238" target="_blank" rel="noreferrer">main_test.go</a></td></tr><tr><td><code>eye run</code> keeps jobs going across restarts, in <code>.eye/journal</code></td><td>✓</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go#L68" target="_blank" rel="noreferrer">runner_test.go</a></td></tr><tr><td>A job started from <code>main</code> needs a key</td><td>✓</td><td>✓ (also when <code>main</code> starts it through a function or entity method it calls)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L95" target="_blank" rel="noreferrer">check_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go#L75" target="_blank" rel="noreferrer">runner_test.go</a></td></tr><tr><td><code>eye runs</code> lists runs, what they wait for, and their steps; a model call&#39;s step shows the model, tokens in and out, dollars and bytes sent and received, and <code>eye runs DIR ID STEP</code> its whole reply</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go#L135" target="_blank" rel="noreferrer">runner_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/runs_model_test.go" target="_blank" rel="noreferrer">runs_model_test.go</a></td></tr><tr><td><code>eye repl</code></td><td>n/a</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/repl/repl_test.go#L41" target="_blank" rel="noreferrer">repl_test.go</a></td></tr><tr><td>Modules as directories; <code>import a.b</code> and <code>import a.b.{Name}</code>; other modules use only what is <code>pub</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L150" target="_blank" rel="noreferrer">check_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/visibility_test.go#L35" target="_blank" rel="noreferrer">visibility_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/lab.eye" target="_blank" rel="noreferrer">lab</a></td></tr><tr><td><code>eye.toml</code> marks a program&#39;s root</td><td>n/a</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/index_test.go#L151" target="_blank" rel="noreferrer">index_test.go</a></td></tr><tr><td><code>modules</code> in <code>eye.toml</code>: more directories to find imports in</td><td>n/a</td><td>✓ (each must exist, be written relative to <code>eye.toml</code> and stay inside the repository; a missing import lists every directory searched)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/eyetoml_test.go#L12" target="_blank" rel="noreferrer">eyetoml_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/deploy/digest/eye.toml" target="_blank" rel="noreferrer">lab deploy/digest</a></td></tr><tr><td><code>parallelMap</code>, <code>both</code>, <code>race</code>, <code>timeout</code>, with waits that overlap</td><td>✓</td><td>✓ (a task&#39;s function, a callback, reads a <code>var</code>&#39;s value at the call and can&#39;t assign it)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tasks/tasks.eye#L18" target="_blank" rel="noreferrer">programs/tasks</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/tasks_test.go#L16" target="_blank" rel="noreferrer">tasks_test.go</a></td></tr><tr><td>A task fails, and the call fails with it</td><td>✓</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/tasks_test.go#L70" target="_blank" rel="noreferrer">tasks_test.go</a></td></tr><tr><td>A task a job starts (<code>parallelMap</code>, <code>both</code>, <code>race</code>, <code>timeout</code>, <code>taskGroup</code>) only computes</td><td>✓</td><td>✓</td><td>✓ (the run fails, should one get past the checker)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L232" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Cheap tasks with small, growing stacks</td><td>n/a</td><td>n/a</td><td>✓ (each task is a Go goroutine; 10,000 waiting tasks hold about 9 KiB each, under a budget of 12 KiB, on either clock)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/manytasks_test.go#L14" target="_blank" rel="noreferrer">manytasks_test.go</a></td></tr><tr><td>Task groups, <code>spawn</code> and channels (v0.2)</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tasks/tasks.eye#L77" target="_blank" rel="noreferrer">programs/tasks</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/channels_test.go#L116" target="_blank" rel="noreferrer">channels_test.go</a></td></tr><tr><td>A failing task cancels its group</td><td>✓</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/channels_test.go#L31" target="_blank" rel="noreferrer">channels_test.go</a></td></tr><tr><td>A group whose tasks all wait for channels nobody can change fails</td><td>✓</td><td>n/a</td><td>✓ (on the system clock, a group inside another task fails once no task outside it can go on)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/channels_test.go#L61" target="_blank" rel="noreferrer">channels_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/channels_test.go#L116" target="_blank" rel="noreferrer">system clock</a></td></tr><tr><td>A channel can&#39;t be live across a <code>!</code></td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L224" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>A task group in a job only computes, in its spawned tasks too</td><td>✓</td><td>✓</td><td>✓ (the run fails)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L200" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Child runs joined with <code>allDone!</code> and <code>firstDone!</code></td><td>✓</td><td>✓ (they take a <code>List(Run(a))</code>; <code>all</code> and <code>first</code> are only the collection functions, and <code>all!</code> or <code>first!</code> is an error that names the wait to write)</td><td>✓ (<code>firstDone!</code> stops the runs that lost, which end as <code>Failed(Killed)</code>; a run paused in either resumes after a restart)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/waiting/waiting.eye#L35" target="_blank" rel="noreferrer">programs/waiting</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/waits_test.go#L139" target="_blank" rel="noreferrer">waits_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L63" target="_blank" rel="noreferrer">types_test.go</a></td></tr></tbody></table><h2 id="entities" tabindex="-1"><a href="/reference/language/entities">Entities</a> <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;[Entities](/reference/language/entities)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>entity</code> with <code>state</code> and defaults; exists on first use</td><td>✓</td><td>✓ (a <code>state</code> field&#39;s type has <code>Save</code>: no functions or secrets)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L5" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td>Methods as atomic transactions; nested entity calls commit together</td><td>✓</td><td>✓</td><td>✓ (an <code>Err</code> commits; a fault part way through a call rolls back every entity it changed, and the jobs it started never run; a call that comes back to an entity already in the call tree shares its state in progress, the outer method goes on from its changes, and the entity commits once)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/entities_test.go#L63" target="_blank" rel="noreferrer">entities_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/entities_test.go#L343" target="_blank" rel="noreferrer">re-entry</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L41" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/entities/entities.eye#L29" target="_blank" rel="noreferrer">programs/entities</a></td></tr><tr><td>One writer at a time per entity</td><td>n/a</td><td>n/a</td><td>✓ (tasks that call one entity&#39;s method at once lose no change, on a test&#39;s clock and on the system clock)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/entities/entities.eye#L21" target="_blank" rel="noreferrer">programs/entities</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/entities_test.go#L175" target="_blank" rel="noreferrer">entities_test.go</a></td></tr><tr><td><code>state</code> fields and methods named without <code>self</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L9" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td>Methods never wait</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L49" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td>Methods and served operations stay inside the program: no <code>net</code>, <code>fs</code>, <code>process</code>, <code>clock</code>, <code>random</code>, <code>env</code>, <code>ffi</code>, <code>secret</code> or <code>wait</code>, themselves or through what they call; output is allowed</td><td>n/a</td><td>✓ (an error at the call that names the effect)</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L715" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>A method starts a job when its transaction commits</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L12" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td>The identity can&#39;t change</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L101" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td><code>read!()</code> snapshots with a <code>version</code>, which no state field may be named; <code>read()</code> outside jobs</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L36" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye#L44" target="_blank" rel="noreferrer">programs/tour</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L23" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td>A job reads entities only in steps: <code>w.phase</code>, a view and <code>E.all</code> are errors in a job and a waiting function; <code>view.read!()</code> and <code>E.all.read!()</code> record a list of snapshots; outside jobs <code>w.phase</code> is <code>w.read().phase</code></td><td>✓</td><td>✓ (an error that names the step to write)</td><td>✓ (a replayed read gives what it first saw)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L875" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/reads.eye#L35" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td>Ending an entity with <code>end(ok)</code> and an <code>Approval</code></td><td>✓</td><td>✓ (only in the entity&#39;s own methods, and only with an <code>Approval</code>)</td><td>✓ (when the transaction commits the state is removed and every store keeps only when it ended and whose approval let it; the entity leaves its views, and a call on it or a read of it faults, after a restart too)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L63" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/entities/entities.eye#L69" target="_blank" rel="noreferrer">programs/entities</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/entities_test.go#L147" target="_blank" rel="noreferrer">entities_test.go</a></td></tr><tr><td><code>@version</code> and <code>migrate from N</code>, chained, without gaps, pure</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/migrations_test.go#L14" target="_blank" rel="noreferrer">migrations_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/migrate_test.go#L15" target="_blank" rel="noreferrer">interp migrate_test.go</a></td></tr><tr><td><code>eye run</code> refuses rows no migration can bring up to date</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/migrate_test.go#L14" target="_blank" rel="noreferrer">cmd/eye migrate_test.go</a></td></tr></tbody></table><h2 id="jobs-and-waiting" tabindex="-1"><a href="/reference/language/jobs-and-waiting">Jobs and waiting</a> <a class="header-anchor" href="#jobs-and-waiting" aria-label="Permalink to &quot;[Jobs and waiting](/reference/language/jobs-and-waiting)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>Jobs saved at every <code>!</code>; a resumed run never repeats a recorded call</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L88" target="_blank" rel="noreferrer">interp_test.go</a></td></tr><tr><td>Runs saved as bytes and finished by a new interpreter</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L112" target="_blank" rel="noreferrer">interp_test.go</a></td></tr><tr><td>Only values with <code>Save</code> live across a <code>!</code>, in a job or a waiting function (its parameters included), and as job arguments; a function only when it is a lambda written there whose captures can be saved, a function declared with <code>fn</code>, or a waiting function&#39;s callback, which its callers check</td><td>✓</td><td>✓</td><td>✓ (a checkpoint saves a function as its code&#39;s name and its captures; a changed lambda faults the paused run)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L617" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L644" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/checkpoint_test.go#L170" target="_blank" rel="noreferrer">checkpoint_test.go</a></td></tr><tr><td>Entity calls commit with the checkpoint</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L112" target="_blank" rel="noreferrer">interp_test.go</a></td></tr><tr><td>The store written in Eyelang, with a <code>Store</code> trait</td><td>n/a</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/memory_test.go#L13" target="_blank" rel="noreferrer">memory_test.go</a></td></tr><tr><td>The journal store for one machine: run records as JSON, a trail written as the steps it gained, one sync for the commits made before the runner does anything outside, and journals from before 2026-10-12 read as they are</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/store_test.go#L16" target="_blank" rel="noreferrer">store_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/journal_test.go" target="_blank" rel="noreferrer">journal_test.go</a></td></tr><tr><td>The Postgres store: <code>eye run --store postgres://…</code>, one runner per database and schema</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/postgres_test.go" target="_blank" rel="noreferrer">postgres_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go" target="_blank" rel="noreferrer">runner_test.go</a></td></tr><tr><td>Runs survive a restart of the runner, and the database stopping or not answering, also before the runner first connects</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/durable_test.go" target="_blank" rel="noreferrer">durable_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/postgres_wait_test.go" target="_blank" rel="noreferrer">postgres_wait_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go" target="_blank" rel="noreferrer">runner_test.go</a></td></tr><tr><td>Jobs resume from saved frames, not by replaying their steps</td><td>n/a</td><td>n/a</td><td>✓ in the interpreter: a checkpoint at each statement of the job&#39;s body; only the steps since replay, and a function the statement calls replays its steps</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/checkpoint_test.go" target="_blank" rel="noreferrer">checkpoint_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/store_test.go" target="_blank" rel="noreferrer">store_test.go</a></td></tr><tr><td>A job changed under a paused run is caught, not replayed into wrong values</td><td>n/a</td><td>n/a</td><td>✓ (<code>eye run</code> refuses to start; a resumed run, or a replayed step for another call, faults)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/checkpoint_test.go" target="_blank" rel="noreferrer">checkpoint_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go" target="_blank" rel="noreferrer">runner_test.go</a></td></tr><tr><td>A waiting run holds no goroutine, only its saved bytes</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/durable_test.go" target="_blank" rel="noreferrer">durable_test.go</a></td></tr><tr><td>A waiting or finished run&#39;s record leaves memory: the journal and the Postgres store keep a handle of about 140 bytes, read the record back when the run wakes, and read no waiting record when they open (20,000 sleeping runs: 32 MB of RSS before, 7 MB now)</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/waiting_test.go" target="_blank" rel="noreferrer">waiting_test.go</a></td></tr><tr><td><code>sleep!</code>, <code>sleepUntil!</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L41" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/notifier/notifier.eye#L242" target="_blank" rel="noreferrer">lab notifier</a></td></tr><tr><td><code>poll!</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L93" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td><code>approval!</code>, with requests published as <code>approvals.requested</code> and answered by <code>approvals.answered</code>, <code>eye approve</code> or <code>eye decline</code></td><td>✓</td><td>✓</td><td>✓: an answer names its request&#39;s <code>id</code> and counts only when its <code>by</code> is the request&#39;s <code>from</code>; another is refused and logged, and the run keeps waiting. <code>eye approve TEXT</code> and test <code>approve(…)</code> refuse text that no waiting approval or several contain; <code>eye approve --id ID</code> answers one. A wait survives a restart of <code>eye run</code> with its id. Any module may still publish an answer (open question 35)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/approvals.eye" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/approvals_test.go" target="_blank" rel="noreferrer">approvals_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/approving/approving.eye#L24" target="_blank" rel="noreferrer">lab approving</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/approve_test.go#L16" target="_blank" rel="noreferrer">approve_test.go</a></td></tr><tr><td><code>next!</code>, which misses no event</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/events/events.eye#L45" target="_blank" rel="noreferrer">programs/events</a></td></tr><tr><td><code>reserve!</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/memory/memory.eye#L42" target="_blank" rel="noreferrer">programs/memory</a></td></tr><tr><td><code>lock!</code></td><td>✓</td><td>✓</td><td>✓ (the store keeps the holder and expiry; a holder still waiting inside when the lock runs out ends as <code>Failed(LockExpired(name))</code>; a held or awaited lock survives a restart)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/waiting/waiting.eye#L111" target="_blank" rel="noreferrer">programs/waiting</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/waits_test.go#L201" target="_blank" rel="noreferrer">waits_test.go</a></td></tr><tr><td><code>run.join!()</code> and <code>Outcome</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L101" target="_blank" rel="noreferrer">programs/limits</a></td></tr><tr><td><code>run.outcome()</code> in tests and <code>main</code>: <code>None</code> while the run is still going</td><td>✓</td><td>✓ (<code>run.join()</code> without <code>!</code> is an error that names <code>join!()</code> in a job and <code>outcome()</code> elsewhere; <code>outcome()</code> in a job is an error that names <code>join!()</code>)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L167" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L83" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>start()</code>, with <code>after:</code>, <code>at:</code> and <code>key:</code></td><td>✓</td><td>✓</td><td>✓ (a start already due runs at once)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L12" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L190" target="_blank" rel="noreferrer"><code>at:</code></a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L208" target="_blank" rel="noreferrer">due</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L118" target="_blank" rel="noreferrer">programs/limits</a></td></tr></tbody></table><h2 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h2><p>Every attribute is declared with where it goes and what it takes, and <code>eye check</code> holds each use to that (<a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L60" target="_blank" rel="noreferrer">check_test.go</a>). The Runs column says whether the runtime does what the attribute says.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>@on(daily(…))</code>, <code>weekdays(…)</code>, <code>every(…)</code></td><td>✓</td><td>✓ (the job takes no parameters, or one <code>Date</code>)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/schedules/schedules.eye#L29" target="_blank" rel="noreferrer">programs/schedules</a></td></tr><tr><td><code>@on(cron(&quot;…&quot;, in: zone))</code></td><td>✓</td><td>✓: a wrong cron line, or one that never fires, is an error at the string</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/schedules/schedules.eye#L75" target="_blank" rel="noreferrer">programs/schedules</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/cron/cron_test.go" target="_blank" rel="noreferrer">cron_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L66" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>@on(enters(view))</code></td><td>✓</td><td>✓ (the job takes one <code>Ref</code> of the view&#39;s entity)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L54" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td><code>@on(leaves(view))</code></td><td>✓</td><td>✓ (as <code>enters</code>)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/views.eye#L49" target="_blank" rel="noreferrer">programs/jobs</a></td></tr><tr><td><code>@on(event(contract.event))</code></td><td>✓</td><td>✓ (the job takes one parameter of the event&#39;s type)</td><td>✓ in tests, for the program&#39;s own events, and under <code>eye run</code> for another service&#39;s, taken as <code>POST /events/&lt;topic&gt;</code></td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/events/events.eye#L37" target="_blank" rel="noreferrer">programs/events</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/relay_test.go" target="_blank" rel="noreferrer">relay_test.go</a></td></tr><tr><td><code>@concurrency(n, by: param)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L73" target="_blank" rel="noreferrer">programs/limits</a></td></tr><tr><td><code>@limit(n, per: duration, by: param)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L92" target="_blank" rel="noreferrer">programs/limits</a></td></tr><tr><td><code>@deadline(duration)</code>, <code>@deadline(time, in: zone)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L101" target="_blank" rel="noreferrer">programs/limits</a></td></tr><tr><td><code>@memory(size)</code>, <code>@priority(p)</code></td><td>✓</td><td>✓</td><td>✓ (what a run holds is its saved state; open question 26); the runner has its cgroup&#39;s limit, or <code>--memory-limit</code></td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/memory/memory.eye#L20" target="_blank" rel="noreferrer">programs/memory</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/cgroup_test.go" target="_blank" rel="noreferrer">cgroup_test.go</a></td></tr><tr><td><code>@budget(usd:, tokens:)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/ai_test.go" target="_blank" rel="noreferrer">ai_test.go</a></td></tr><tr><td><code>@version(N)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/migrations_test.go#L14" target="_blank" rel="noreferrer">migrations_test.go</a></td></tr><tr><td><code>@key</code>, <code>@reconcile</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye#L44" target="_blank" rel="noreferrer">programs/tour</a></td></tr><tr><td><code>@http</code>, <code>@auth</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L24" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td><code>@port</code>, <code>@allow</code></td><td>✓</td><td>✓: a served contract and one with <code>@allow</code> need <code>@port</code>; a call from a module <code>@allow</code> doesn&#39;t list, a name that isn&#39;t a module, and any call under <code>@allow(nobody)</code> are errors</td><td>✓: <code>eye run</code> serves a served contract on its <code>@port</code> (<code>&lt;MODULE&gt;_PORT</code> moves it); <code>@allow</code> isn&#39;t enforced at the port until network policy (6.5)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/ports_test.go#L41" target="_blank" rel="noreferrer">ports_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/serve_test.go" target="_blank" rel="noreferrer">serve_test.go</a></td></tr><tr><td><code>@fresh</code>, <code>@destructive</code></td><td>✓</td><td>✓ on commands; <code>@destructive</code> on a function adds <code>approval: Approval</code></td><td>✓ on commands, and on a model&#39;s tool</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/fresh_test.go#L61" target="_blank" rel="noreferrer">fresh_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/contracts/contracts.eye#L92" target="_blank" rel="noreferrer">programs/contracts</a></td></tr><tr><td><code>@unwitnessed(&quot;why&quot;)</code></td><td>✓</td><td>✓ (on a function, job, test or type: its reads of fields no recording has are allowed)</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye#L172" target="_blank" rel="noreferrer">lab: digest</a></td></tr><tr><td><code>@library</code>, <code>@host</code></td><td>✓</td><td>✓: a program&#39;s extern fn needs exactly one, and a C function&#39;s types must cross to C</td><td>✓ (see &quot;Calling C and Go&quot; below)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/host/host_test.go" target="_blank" rel="noreferrer">host_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/host/clib/clib_test.go" target="_blank" rel="noreferrer">clib_test.go</a></td></tr></tbody></table><h2 id="views-and-triggers" tabindex="-1"><a href="/reference/language/views-and-triggers">Views and triggers</a> <a class="header-anchor" href="#views-and-triggers" aria-label="Permalink to &quot;[Views and triggers](/reference/language/views-and-triggers)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>A view is a pipeline over an entity set, kept up to date</td><td>✓</td><td>✓ (its pipeline stays inside the program, as a method does)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L24" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/views.eye#L15" target="_blank" rel="noreferrer">read by name</a></td></tr><tr><td>A view must start from an entity set</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L110" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td><code>enters(view)</code> and <code>leaves(view)</code>, each time an entity enters or leaves</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/jobs.eye#L54" target="_blank" rel="noreferrer">programs/jobs</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/jobs/views.eye#L61" target="_blank" rel="noreferrer">enters, leaves, enters again</a></td></tr><tr><td>Pipelines over entities compiled to SQL</td><td>n/a</td><td>n/a</td><td>— (they run in memory, over the entities the store holds; SQL waits for several runners on one database, open question 28)</td><td></td></tr></tbody></table><h2 id="contracts-talking-to-other-services" tabindex="-1"><a href="/reference/language/contracts-talking-to-other-services">Contracts: talking to other services</a> <a class="header-anchor" href="#contracts-talking-to-other-services" aria-label="Permalink to &quot;[Contracts: talking to other services](/reference/language/contracts-talking-to-other-services)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>contract</code> with commands, queries and events</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/notify/notify.eye#L16" target="_blank" rel="noreferrer">tour notify</a></td></tr><tr><td><code>import</code> as a typed edge: a wrong port or caller is a compile error</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/ports_test.go#L41" target="_blank" rel="noreferrer">ports_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/ports_test.go#L154" target="_blank" rel="noreferrer">lab</a></td></tr><tr><td>Network policy from contracts: <code>eye gen policy</code> writes a Kubernetes <code>NetworkPolicy</code> per contract with <code>@port</code>, letting in the modules that call it and <code>@allow</code> lets</td><td>n/a</td><td>✓</td><td>✓: pods by <code>eyelang.module</code>, namespace from <code>--namespace</code>; no egress rules</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/netpolicy/netpolicy_test.go" target="_blank" rel="noreferrer">netpolicy_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/netpolicy/testdata/lab.yaml" target="_blank" rel="noreferrer">the lab&#39;s policy</a></td></tr><tr><td>Commands can return <code>Uncertain</code>, which must be handled or reconciled; a command that returns a record too, whose fields can&#39;t be read before then</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L127" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/worlds.eye#L26" target="_blank" rel="noreferrer">tour worlds</a></td></tr><tr><td>A command&#39;s outcome, with or without <code>Uncertain</code>, <code>Stale</code> and <code>Expired</code>, can&#39;t be dropped by a statement: it is matched, used or discarded with <code>let _ = …</code></td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/drop_test.go#L46" target="_blank" rel="noreferrer">drop_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/trains/trains.eye#L83" target="_blank" rel="noreferrer">lab trains</a></td></tr><tr><td><code>.reconcile!()</code> through a query, resending only on <code>None</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye#L44" target="_blank" rel="noreferrer">programs/tour</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L136" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>@reconcile(send)</code>: reconciling resends with the same key</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye#L151" target="_blank" rel="noreferrer">lab digest</a></td></tr><tr><td>A request never sent is retried, not <code>Uncertain</code></td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L289" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td>Queries retried, then <code>Failed(Unavailable(…))</code>; <code>Result(T, HttpError)</code> gets the failures</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L289" target="_blank" rel="noreferrer">services_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/web/web.eye#L16" target="_blank" rel="noreferrer">lab web</a></td></tr><tr><td>Events published on commit or as a job&#39;s step; <code>@key</code> starts one run per key</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/events/events.eye#L37" target="_blank" rel="noreferrer">programs/events</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/notifier/notifier.eye#L191" target="_blank" rel="noreferrer">lab notifier</a></td></tr><tr><td><code>@fresh</code> and <code>@destructive</code> commands</td><td>✓</td><td>✓ A <code>@fresh</code> command takes <code>basedOn: Version</code> and may be <code>Stale</code> or <code>Expired</code>, which a match must handle; a <code>@destructive</code> one takes an <code>Approval</code>; a served <code>impl</code> takes both and answers <code>Stale</code></td><td>✓ in calls, fakes and an <code>impl</code>; over HTTP <code>basedOn</code> and <code>approval</code> go as arguments, and 409 is <code>Stale</code>, 410 <code>Expired</code></td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/fresh_test.go#L61" target="_blank" rel="noreferrer">fresh_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/contracts/contracts.eye#L92" target="_blank" rel="noreferrer">programs/contracts</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L382" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td>A contract&#39;s operations are its module&#39;s functions</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye#L44" target="_blank" rel="noreferrer">programs/tour</a></td></tr><tr><td>Serving a contract with <code>impl Contract { … }</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/notifier/notifier.eye#L233" target="_blank" rel="noreferrer">lab notifier</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L297" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>Values as JSON, one shape everywhere</td><td>n/a</td><td>n/a</td><td>✓ (<code>toJson</code> compiled by <code>eye build</code> too, byte for byte as the interpreter writes it)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L24" target="_blank" rel="noreferrer">services_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/json/json.eye" target="_blank" rel="noreferrer">cgen/testdata/json</a></td></tr><tr><td>Over HTTP: paths, query parameters, key header, <code>status:</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L24" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td><code>eye run</code> serves a contract over HTTP on its <code>@port</code>: routed by <code>@http</code>, the one JSON shape, <code>@auth</code> checked (401), one transaction per request, <code>status:</code> for the reply</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/listen_test.go" target="_blank" rel="noreferrer">listen_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/serve_test.go" target="_blank" rel="noreferrer">serve_test.go</a> (the lab&#39;s notifier serving Notify to a second program)</td></tr><tr><td>Events between programs: <code>eye run</code> takes another service&#39;s events it consumes as <code>POST /events/&lt;topic&gt;</code> under the contract&#39;s <code>@auth</code> (202 once in the journal, 400, 401, a repeated <code>@key</code> starts nothing), on its served ports and <code>EYE_EVENTS_PORT</code>; it sends the events of a contract it serves to <code>&lt;MODULE&gt;_EVENTS_URL</code>, from deliveries saved with the commit, again after no answer or a 5xx, in order per subscriber, across restarts</td><td>n/a</td><td>n/a</td><td>✓; events of a contract without <code>@auth</code> aren&#39;t taken, and <code>eye gen policy</code> writes no rule for events (open question 48)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/relay_test.go" target="_blank" rel="noreferrer">relay_test.go</a> (two <code>eye run</code>s, a restart, retries and refusals), <a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/playground/playground_test.go" target="_blank" rel="noreferrer">playground_test.go</a> (the bank&#39;s event reaching the shop in memory)</td></tr><tr><td>A service&#39;s URL from the environment; a served contract calls itself</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L24" target="_blank" rel="noreferrer">services_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/notifier/notifier.eye#L233" target="_blank" rel="noreferrer">lab notifier</a></td></tr><tr><td>Fakes from recordings, checked against the contract; several exchanges for one operation and key answer in turn</td><td>✓</td><td>✓ (reading a field no recording the tests replay contains is an error)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tour/tour.eye#L57" target="_blank" rel="noreferrer">programs/tour</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/docs/examples/webhook-delivery/main.eye#L95" target="_blank" rel="noreferrer">examples/webhook-delivery</a></td></tr><tr><td><code>http.get!</code> for services without a contract; a request that never reached the server is sent again for about a minute, then <code>NoAnswer</code> says why in words; tests answer it from recordings by URL with <code>fakes(http, …)</code></td><td>✓</td><td>✓</td><td>✓ (compiled by <code>eye build</code> as a host call the Go runner answers; a binary without the runner faults, saying so: <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/hostcalls/hostcalls.eye" target="_blank" rel="noreferrer">cgen/testdata/hostcalls</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/web/web.eye#L30" target="_blank" rel="noreferrer">lab web</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/fakes_http_test.go" target="_blank" rel="noreferrer">fakes_http_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L24" target="_blank" rel="noreferrer">services_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/unreachable_test.go" target="_blank" rel="noreferrer">unreachable_test.go</a></td></tr><tr><td>Generated types, clients and stubs for other languages: <code>eye gen go</code> and <code>eye gen ts</code> write each contract module&#39;s types in the one JSON shape, a client over <code>@http</code>, a server stub that routes as <code>eye run</code> does, and a sender for each event</td><td>n/a</td><td>✓: tuples, maps without string keys, unnamed records and <code>extern type</code>s are refused</td><td>partial: Go and TypeScript; no Rust or Python; operations without <code>@http</code> get no method; the TypeScript stub checks that arguments are there, not their shapes</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/codegen/codegen_test.go" target="_blank" rel="noreferrer">codegen_test.go</a> (golden <a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/codegen/testdata/notify.ts.golden" target="_blank" rel="noreferrer">Notify</a> and Miniflux, <code>go vet</code>, <code>tsc --strict</code>), <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/gen_roundtrip_test.go" target="_blank" rel="noreferrer">gen_roundtrip_test.go</a> (every type of the lab&#39;s contracts through the generated clients and stubs to <code>eye run</code> and back)</td></tr></tbody></table><h2 id="calling-c-and-go" tabindex="-1"><a href="/reference/language/calling-c-and-go">Calling C and Go</a> <a class="header-anchor" href="#calling-c-and-go" aria-label="Permalink to &quot;[Calling C and Go](/reference/language/calling-c-and-go)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>extern fn</code> with a signature and no body</td><td>✓</td><td>✓ (calling a program&#39;s own adds <code>ffi</code> unless it states its uses; a program&#39;s own needs exactly one of <code>@library</code> and <code>@host</code>, and a C function&#39;s parameter or result that can&#39;t cross to C is an error at its type)</td><td>✓: the standard library&#39;s own (<code>ai.generate</code>, <code>http.get</code>), a program&#39;s <code>@host</code> and <code>@library</code> ones, and in a job each is a recorded step</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/std/http.eye" target="_blank" rel="noreferrer">std/http.eye</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>@library</code>: C functions</td><td>✓</td><td>✓ (no <code>Int</code>, no <code>Bytes</code> result; <code>Option</code> of an <code>extern type</code> for a pointer that may be NULL)</td><td>✓: loaded at run time without cgo (<code>internal/ffi</code>, on purego); <code>Bool</code>, <code>Byte</code>, the fixed-width integers, <code>Float</code>, <code>String</code> and <code>Bytes</code> copied, <code>extern type</code> values as pointers; a missing library or symbol is reported before <code>main</code>, NULL without <code>Option</code> is a fault. The released <code>eye</code> for Linux is static and has no loader: build with <code>-tags clib</code></td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/host/clib/clib_test.go" target="_blank" rel="noreferrer">clib_test.go</a> (zlib&#39;s <code>crc32</code> and gzip functions)</td></tr><tr><td><code>@host</code>: functions from a Go program that embeds Eyelang</td><td>✓</td><td>✓ (its types are checked by <code>Register</code>, against the Go function)</td><td>✓: the embedding API, package <code>eyelang/host</code> (<code>Load</code>, <code>Register</code>, <code>Run</code>, <code>Test</code>); <code>Register</code> checks the Go function&#39;s type against the declaration; a host function nothing registered is reported before <code>main</code>; a panic is a fault</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/host/host_test.go" target="_blank" rel="noreferrer">host_test.go</a></td></tr></tbody></table><h2 id="ai-models-and-agents" tabindex="-1"><a href="/reference/language/ai-models-and-agents">AI models and agents</a> <a class="header-anchor" href="#ai-models-and-agents" aria-label="Permalink to &quot;[AI models and agents](/reference/language/ai-models-and-agents)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td><code>ai.generate!</code>, with the schema taken from the type expected, <code>effort:</code> (<code>ai.Effort</code>), and a provider that can&#39;t be reached or answers 429 or a 5xx tried again for about a minute</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L243" target="_blank" rel="noreferrer">services_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/ai_test.go#L381" target="_blank" rel="noreferrer">maps, tuples, times</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L376" target="_blank" rel="noreferrer">types_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/unreachable_test.go" target="_blank" rel="noreferrer">unreachable_test.go</a></td></tr><tr><td>Only types with <code>Schema</code> can be asked for</td><td>✓</td><td>✓ (a call with no type to ask for, a type that refers to itself and <code>()</code> are errors at the call)</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L249" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td>A reply is checked, asked for once more, then <code>Err(Malformed(…))</code></td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L243" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td>Providers: Anthropic, OpenAI and a gateway, by <code>provider:</code> or by the model&#39;s name</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/ai_test.go" target="_blank" rel="noreferrer">ai_test.go</a></td></tr><tr><td>In a job, a model call is a recorded step</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye#L128" target="_blank" rel="noreferrer">lab digest</a></td></tr><tr><td>Tests replay recordings with <code>fakes(ai, …)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L272" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td><code>eye test --live</code> and <code>--record</code>: the named modules&#39; calls go to the real services, a test that can&#39;t reach one is skipped, and <code>--record</code> writes their answers, without secrets, as the recordings the fakes read</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/live_test.go" target="_blank" rel="noreferrer">live_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/live_test.go" target="_blank" rel="noreferrer">cmd/eye live_test.go</a></td></tr><tr><td>A test doesn&#39;t reach the network: a call without <code>fakes(…)</code> for its module, outside <code>--live</code>, fails the test</td><td>n/a</td><td>n/a</td><td>✓: a contract&#39;s operation, <code>http.get</code> and <code>ai.generate</code> fail the test at the call with the fakes or <code>--live</code> to add, even when the service&#39;s address or key is set; a program&#39;s call to a contract it serves itself stays in the process</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/live_test.go#L378" target="_blank" rel="noreferrer">live_test.go</a></td></tr><tr><td><code>@budget</code>: tokens and dollars, counted again on replay, the call that would go over not sent</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/ai_test.go" target="_blank" rel="noreferrer">ai_test.go</a></td></tr><tr><td>Tools: functions passed as <code>tools:</code>, each converted to an <code>ai.Tool</code>, with its schema from its parameters and its description from its <code>##</code> comment</td><td>✓</td><td>✓ (parameters and result need <code>Schema</code>; a lambda, an <code>extern fn</code> or a generic function is refused)</td><td>✓ for Anthropic and chat completions, and from recordings</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/tools_test.go#L46" target="_blank" rel="noreferrer">tools_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/tools_test.go#L45" target="_blank" rel="noreferrer">interp tools_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tools/tools.eye#L46" target="_blank" rel="noreferrer">programs/tools</a></td></tr><tr><td>A tool&#39;s effects count where it is named; a model call&#39;s own effect is <code>net Ai.generate</code></td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/tools_test.go#L46" target="_blank" rel="noreferrer">tools_test.go</a></td></tr><tr><td>In a job, each model reply and each tool&#39;s result is a step, so a restarted run runs no tool twice</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go#L332" target="_blank" rel="noreferrer">runner_test.go</a></td></tr><tr><td><code>@destructive</code> tools: each call waits for <code>approve:</code>, usually <code>approval!</code></td><td>✓</td><td>✓ (a call whose <code>tools:</code> names one gives <code>approve:</code>)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/tools/tools.eye#L46" target="_blank" rel="noreferrer">programs/tools</a></td></tr><tr><td>Coding agents: the <code>agents</code> module</td><td>✓</td><td>— (no such module)</td><td>—</td><td><a href="https://github.com/ruxxzebre/eyelang/issues/60" target="_blank" rel="noreferrer">#60</a> (6.8)</td></tr></tbody></table><h2 id="time-secrets-tests" tabindex="-1"><a href="/reference/language/time-secrets-tests">Time, secrets, tests</a> <a class="header-anchor" href="#time-secrets-tests" aria-label="Permalink to &quot;[Time, secrets, tests](/reference/language/time-secrets-tests)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Parses</th><th>Checks</th><th>Runs</th><th>Shown by</th></tr></thead><tbody><tr><td>Schedules in a zone; skipped and repeated times at daylight-saving changes</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/schedules/schedules.eye#L42" target="_blank" rel="noreferrer">programs/schedules</a></td></tr><tr><td><code>onGap: Shift | Skip</code> and <code>onOverlap: First | Second | Both</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/schedules/schedules.eye#L96" target="_blank" rel="noreferrer">programs/schedules</a></td></tr><tr><td>A missed firing runs once on restart</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/store_test.go#L355" target="_blank" rel="noreferrer">store_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/store_test.go#L391" target="_blank" rel="noreferrer">a cron across restarts</a></td></tr><tr><td><code>at.date(in:)</code>, <code>at.time(in:)</code>, <code>time.next(…)</code>, <code>day.at(…)</code>, <code>day.format(…)</code>, <code>at.unix()</code>; a range of times of day, <code>23:00..08:00</code>, holds the times that wrap midnight, and has a <code>start</code> and an <code>end</code></td><td>✓</td><td>✓</td><td>✓ (compiled by <code>eye build</code> too: <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/testdata/times/times.eye" target="_blank" rel="noreferrer">cgen: times</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye#L344" target="_blank" rel="noreferrer">lab digest</a></td></tr><tr><td><code>t.format(&quot;%H:%M&quot;)</code>: a time of day written out, with <code>%H</code>, <code>%I</code>, <code>%M</code>, <code>%S</code> and <code>%p</code></td><td>✓</td><td>✓</td><td>✓ (compiled by <code>eye build</code> too, with the same formatter as dates)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/times_test.go" target="_blank" rel="noreferrer">times_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye#L475" target="_blank" rel="noreferrer">lab digest</a></td></tr><tr><td><code>secret(name)</code> from the environment or <code>$EYE_SECRETS</code></td><td>✓</td><td>✓</td><td>partial: the environment is tested; <code>$EYE_SECRETS</code> works but has no test</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/services_test.go#L24" target="_blank" rel="noreferrer">services_test.go</a></td></tr><tr><td><code>env.get(name)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/web/web.eye#L16" target="_blank" rel="noreferrer">lab web</a></td></tr><tr><td><code>test</code> blocks, including those of imported modules</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L44" target="_blank" rel="noreferrer">interp_test.go</a></td></tr><tr><td><code>with clock(…)</code>, <code>advance(…)</code>, <code>with fakes(…)</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/schedules/schedules.eye#L35" target="_blank" rel="noreferrer">programs/schedules</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/trains/trains.eye#L200" target="_blank" rel="noreferrer">lab trains</a></td></tr><tr><td><code>let sent = fakes(…)</code>, <code>with sent</code>, and <code>sent.calls(op)</code>: the calls a fake answered, as records of their arguments and key; <code>fakes(…)</code> is a <code>Fakes</code>, and <code>calls</code> on another handler is a check error</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/events/events.eye#L54" target="_blank" rel="noreferrer">programs/events</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/digest/digest.eye" target="_blank" rel="noreferrer">lab digest</a></td></tr><tr><td><code>with memory(…)</code>: the memory a test&#39;s runner has, which <code>@memory</code> and <code>reserve!</code> are admitted against</td><td>✓</td><td>✓ (a <code>Handler</code> that takes a <code>Size</code>)</td><td>✓ (raising it runs what waited for memory and now fits)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/memory/memory.eye#L91" target="_blank" rel="noreferrer">programs/memory</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/types_test.go#L366" target="_blank" rel="noreferrer">types_test.go</a></td></tr><tr><td><code>with</code> only in tests</td><td>✓</td><td>✓</td><td>n/a</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/check_test.go#L108" target="_blank" rel="noreferrer">check_test.go</a></td></tr><tr><td>Published events start and wake runs in tests; <code>approve</code> and <code>decline</code></td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/lab/access/access.eye#L180" target="_blank" rel="noreferrer">lab access</a></td></tr><tr><td><code>expect</code> shows the value it got</td><td>✓</td><td>✓</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L212" target="_blank" rel="noreferrer">main_test.go</a></td></tr><tr><td>A run that stops on a bug fails its test; a declared outcome doesn&#39;t</td><td>n/a</td><td>n/a</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/testdata/programs/limits/limits.eye#L101" target="_blank" rel="noreferrer">programs/limits</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/interp_test.go#L153" target="_blank" rel="noreferrer">interp_test.go</a></td></tr></tbody></table><h2 id="tooling" tabindex="-1">Tooling <a class="header-anchor" href="#tooling" aria-label="Permalink to &quot;Tooling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Status</th><th>Shown by</th></tr></thead><tbody><tr><td><code>eye fmt</code></td><td>✓ One style with no options; <code>--check</code>; reads standard input; refuses files with syntax errors; recursive searches skip hidden directories and <code>node_modules</code> unless named explicitly; a program&#39;s directory gets each public function&#39;s <code>uses</code> clause written from its body (<code>--syntax-only</code> skips it); <code>--check</code> reuses a saved result while every file it read is unchanged, and <code>--cold</code> checks afresh; at a terminal it ends with the files, lines and time it took, and <code>--stats</code> breaks the time down by phase and names the slowest files</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/syntax/format_test.go#L72" target="_blank" rel="noreferrer">format_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L96" target="_blank" rel="noreferrer">main_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/fmt_test.go" target="_blank" rel="noreferrer">fmt_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/fmt_cache_test.go" target="_blank" rel="noreferrer">fmt_cache_test.go</a></td></tr><tr><td><code>eye parse</code></td><td>✓ The syntax tree, or an S-expression with <code>--sexp</code></td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L58" target="_blank" rel="noreferrer">main_test.go</a></td></tr><tr><td><code>eye check</code></td><td>✓ Syntax, names, types, matches, effects and attributes; <code>--syntax</code> for syntax alone; a declaration with a syntax error is skipped and the rest checked, with no undefined-name errors for what it declares (<a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/broken_test.go" target="_blank" rel="noreferrer">broken_test.go</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L193" target="_blank" rel="noreferrer">main_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/check/classes_test.go" target="_blank" rel="noreferrer">classes_test.go</a></td></tr><tr><td><code>eye test</code></td><td>✓ <code>--run</code> to filter, <code>-v</code> to show logs, <code>--live</code> to call the real services of the modules named, <code>--record</code> to write what they answered as recordings</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L212" target="_blank" rel="noreferrer">main_test.go</a></td></tr><tr><td><code>eye run</code> and <code>eye runs</code></td><td>✓ The journal in <code>.eye/journal</code>, a Postgres database with <code>--store</code> or <code>$EYE_STORE</code>, or <code>--memory</code>; survives a kill; stops on Ctrl-C or SIGTERM, <code>main</code> too while it waits; <code>eye runs --retry ID</code> and <code>--retry-failed</code> start a run that failed as <code>Unavailable</code> or <code>DeadlinePassed</code> again, replaying its steps and keeping its id and key, on the journal and on Postgres, through the runner&#39;s inbox while <code>eye run</code> holds the store (<a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/retry_test.go#L51" target="_blank" rel="noreferrer">retry_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/retry_test.go#L113" target="_blank" rel="noreferrer">interp&#39;s retry_test.go</a>); starts with a line naming the program, store, memory and jobs, a line per contract it serves and the port, and a line per port it takes events on</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go#L40" target="_blank" rel="noreferrer">runner_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/startup_test.go" target="_blank" rel="noreferrer">startup_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/signal_test.go#L16" target="_blank" rel="noreferrer">signal_test.go</a></td></tr><tr><td><code>eye run --fresh</code></td><td>✓ Starts over with an empty journal, kept as <code>JOURNAL.old</code>; refused with a database or <code>--memory</code>; a run that has nothing to do says so</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/runner_test.go" target="_blank" rel="noreferrer">runner_test.go</a></td></tr><tr><td><code>eye doc</code></td><td>✓ The API reference in Markdown from <code>##</code> comments, with the public methods of a type&#39;s <code>impl</code> and an entity&#39;s under it; fails on a link that names nothing; writes to <code>./api</code> or <code>--out</code>, and replaces that folder only if it is missing, empty or its own output</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/apidoc/apidoc_test.go#L12" target="_blank" rel="noreferrer">apidoc_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L427" target="_blank" rel="noreferrer">main_test.go</a></td></tr><tr><td><code>eye lsp</code>: diagnostics, formatting, outline, folding, semantic tokens; hover, completion and definition in a file with a half-typed declaration (<a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/halftyped_test.go" target="_blank" rel="noreferrer">halftyped_test.go</a>)</td><td>✓</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/server_test.go#L136" target="_blank" rel="noreferrer">server_test.go</a></td></tr><tr><td><code>eye lsp</code>: go to definition and find references, also from the command line</td><td>✓ Into modules, the prelude, the standard library and the Go behind built-ins</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/definition_test.go#L15" target="_blank" rel="noreferrer">definition_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cmd/eye/main_test.go#L272" target="_blank" rel="noreferrer">main_test.go</a></td></tr><tr><td><code>eye lsp</code>: go to type definition, to the innermost declared types of a field&#39;s, a local&#39;s, a parameter&#39;s, a call&#39;s or a literal&#39;s type, also from the command line (<code>--type-definition</code>)</td><td>✓ Generic and wrapped types, maps with two declared types, entity references and built-in types</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/typedef_test.go" target="_blank" rel="noreferrer">typedef_test.go</a></td></tr><tr><td><code>eye lsp</code>: hover</td><td>✓ A name&#39;s signature and its doc comment</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/hover_test.go#L13" target="_blank" rel="noreferrer">hover_test.go</a></td></tr><tr><td><code>eye lsp</code>: completion</td><td>✓ Keywords and the names in scope; after <code>x.</code>, a module&#39;s declarations, or the fields and methods of <code>x</code>&#39;s type and then the functions in scope that take <code>x</code> first</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/completion_test.go#L117" target="_blank" rel="noreferrer">completion_test.go</a></td></tr><tr><td><code>eye lsp</code>: the inferred effects of private functions</td><td>✓ Hover shows them: <code>Its effects, as inferred: uses {clock}</code>, or none</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/hover_test.go#L110" target="_blank" rel="noreferrer">hover_test.go</a></td></tr><tr><td>Self-hosting: Eyelang&#39;s lexer in Eyelang (S.1)</td><td>✓ The same tokens, spans and flags as <code>syntax/lexer.go</code> on every file of the conformance suite and every source of the tree-sitter corpus, interpreted and compiled; <code>testdata/bench/lexer</code> races it against the Go lexer: natively it takes 0.65 times as long and 0.33 times the memory (62.8 MB against 191.6, after 7.5 and 7.13)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/lexer_test.go" target="_blank" rel="noreferrer">lexer_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/programs/lexer" target="_blank" rel="noreferrer">programs/lexer</a>, <a href="https://github.com/ruxxzebre/eyelang/tree/dev/testdata/bench/lexer" target="_blank" rel="noreferrer">bench/lexer</a></td></tr><tr><td><code>eye repl</code></td><td>✓ Expressions with their types, bindings, declarations, jobs on a clock that <code>:advance</code> moves</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/repl/repl_test.go#L113" target="_blank" rel="noreferrer">repl_test.go</a></td></tr><tr><td>Speed on large programs</td><td>partial: a million lines check in 3.8 s, and <code>eye fmt --check</code> on a million lines across 4,480 programs takes 5.3 s, checking them in parallel; writing a million lines&#39; C takes 29 s, but an optimised build of 100,000 lines takes 4 minutes, so a build of a million isn&#39;t practical yet. The targets (a minute, then 10 s, then 1 s) are open question 47</td><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/benchmarks" target="_blank" rel="noreferrer">benchmarks</a></td></tr><tr><td>VS Code extension</td><td>✓ TextMate highlighting and the <code>eye lsp</code> client</td><td><a href="https://github.com/ruxxzebre/eyelang/tree/dev/editors/vscode/test" target="_blank" rel="noreferrer">editors/vscode/test</a></td></tr><tr><td>The online playground (open question 34)</td><td>✓ <a href="/playground">A page of this site</a> that checks, runs, tests and formats a program of several files in the browser, with errors at their spans, hover, completion, go to definition and the parser&#39;s highlighting; <code>eye</code> built for WebAssembly (<code>cmd/eye-wasm</code>) in a worker; jobs on a clock that skips ahead, as far as a run waits (up to a year), with schedules a day past the last run; recordings read from memory, and a contract nothing in the page serves answered from them in a run, each answer shown; <code>fs</code> on the page&#39;s files, writes kept in memory, and an empty directory in memory for each test; the tutorial&#39;s and the guide&#39;s programs as examples; links that hold a program; two programs calling each other through a contract, the one in a directory with its own <code>eye.toml</code> served in memory with no port, each request and event shown as it crosses (<a href="https://github.com/ruxxzebre/eyelang/tree/dev/docs/examples/shop-and-bank" target="_blank" rel="noreferrer">shop-and-bank</a>)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/playground/playground_test.go" target="_blank" rel="noreferrer">playground_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/internal/lsp/workspace_test.go" target="_blank" rel="noreferrer">workspace_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/virtual_test.go" target="_blank" rel="noreferrer">virtual_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/inmemory_test.go" target="_blank" rel="noreferrer">inmemory_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/interp/memfs_test.go" target="_blank" rel="noreferrer">memfs_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/docs/test/playground.e2e.mjs" target="_blank" rel="noreferrer">playground.e2e.mjs</a></td></tr><tr><td><code>eye build</code></td><td>✓ for the core language: C11 from the low IR with <code>#line</code> directives, compiled by the pinned zig (<code>-O2</code>, or <code>-O0 -g</code> with <code>-g</code>) for this machine or, with <code>--target</code>, any of the five release targets; <code>--test</code> makes a binary that runs the test blocks as <code>eye test</code> does; at <code>-O2</code> the runtime and the program compile as one unit so the runtime&#39;s fast paths inline; object files cached by content hash, so a rebuild of an unchanged program only links; the runtime brings its own allocator (free lists by size class) and integer formatting, and counts objects (<code>EYE_ALLOCS</code>), which a test checks balance; <code>--emit-c</code> writes the C. A program with entities, jobs, views or contracts gets an error that says they aren&#39;t compiled yet</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/cgen_test.go" target="_blank" rel="noreferrer">cgen_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/alloc_test.go" target="_blank" rel="noreferrer">alloc_test.go</a></td></tr><tr><td><code>eye build --runner</code>: the program linked into the Go runner (B′)</td><td>partial: <code>main</code> and a <code>--test</code> build&#39;s tests run from the runner&#39;s <code>main</code> through cgo, built by the pinned Go (<code>internal/gotool</code>) with zig as the C compiler: one static binary on Linux, cross-built for linux/arm64 and both macOS targets; the runner runs a compiled program&#39;s <code>main</code>, tests, entity methods and jobs through <code>interp.Native</code> and <code>cgen/hosted/eye_host.h</code>, answers its callbacks (entity calls and reads, starts, publishing, host functions) and takes its host-function steps, on the journal and on Postgres, resuming after a restart, with the program carried in the binary; shown with a hand-written C stand-in, since cgen doesn&#39;t write those entry points yet (7.6, with 7.9)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/runner_test.go" target="_blank" rel="noreferrer">runner_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/hosted_test.go" target="_blank" rel="noreferrer">hosted_test.go</a></td></tr><tr><td>Native compilation with reference counting (v0.4)</td><td>partial: the core language compiles, and the tests of every program <code>eye build</code> compiles (core, traits, the lexer and cgen&#39;s own) pass natively on linux/amd64 at both <code>-O0 -g</code> and <code>-O2</code>, with <code>eye test -v</code>&#39;s output line for line; counting is precise (7.5): the low IR drops each value after its last use, borrows what a function only reads and updates in place whatever the shape around the update, and a count of objects balances in every compilable program; values are laid out by type (7.13): enums as a byte, records, tuples and variant types up to 64 bytes as C structs, <code>Option</code> in a niche or behind a tag, large and recursive types boxed, lists, sets and maps holding their elements inline, and a list&#39;s slice sharing its buffer; <code>toJson</code>, saved values (an encoder and a decoder per type, as the runner will call them) and the host calls <code>http.get</code> and the <code>regex</code> module (answered by the Go runner) compile (7.9); strings and <code>Bytes</code> are still objects, not views, so their slices copy; reuse of matched cells and fault regions are 7.12; the runner doesn&#39;t host compiled code yet (7.6)</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/cgen_test.go" target="_blank" rel="noreferrer">cgen_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/updates_test.go" target="_blank" rel="noreferrer">updates_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/cgen/alloc_test.go" target="_blank" rel="noreferrer">alloc_test.go</a>, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/lir/count_test.go" target="_blank" rel="noreferrer">count_test.go</a></td></tr><tr><td>Native code faster than Go and on less memory (7.7)</td><td>partial: <code>go run ./tools/bench</code> builds nine benchmarks, Eyelang&#39;s lexer among them, natively and in Go, compares outputs, prints time and peak memory against Go and the interpreter, and <code>--check</code> fails on a regression against <a href="/internals/benchmarks">the recorded results</a>; after 7.5 and 7.13 native code is faster than Go on trees, records, strings, logs and the lexer, and uses less memory on all but strings, at 0.45–1.69× Go&#39;s time (0.85× on the geometric mean); fib, mandelbrot and maps are still slower, and lists level with Go</td><td><a href="https://github.com/ruxxzebre/eyelang/blob/dev/tools/bench/bench_test.go" target="_blank" rel="noreferrer">bench_test.go</a></td></tr></tbody></table>',47)])])}const u=t(d,[["render",s]]);export{g as __pageData,u as default};
